/**
 * RFC-4180 CSV writer used by both export routes (issues and the audit log).
 *
 * The rules that matter: fields containing a comma, a double quote or a line
 * break are wrapped in double quotes and every embedded quote is doubled;
 * rows are separated by CRLF; column order comes from the caller, never from
 * object key order.
 */

const NEEDS_QUOTING = /[,\r\n]/;

export function escapeCsvValue(value: string | number | boolean | null): string {
  if (value === null) return "";
  const text = String(value);
  if (!NEEDS_QUOTING.test(text)) return text;
  return `"${text.replace(/"/g, '""')}"`;
}

/**
 * Serialises `rows` using `columns` as both the header line and the field
 * order. A column missing from a row is written as an empty field.
 */
export function toCsv(
  rows: readonly Readonly<Record<string, string | number | boolean | null>>[],
  columns: readonly string[],
): string {
  const lines: string[] = [columns.map(escapeCsvValue).join(",")];

  for (const row of rows) {
    lines.push(
      columns
        .map((column) => escapeCsvValue(row[column] ?? null))
        .join(","),
    );
  }

  return lines.join("\r\n");
}

/** The headers an export Route Handler returns alongside the CSV body. */
export function csvResponseHeaders(
  filename: string,
): Readonly<Record<string, string>> {
  const safe = filename.replace(/[^A-Za-z0-9._-]/g, "-");
  return {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": `attachment; filename="${safe}"`,
    "Cache-Control": "no-store",
  };
}
/** Quoting, embedded newlines and column ordering. */
import { describe, expect, it } from "vitest";
import { csvResponseHeaders, escapeCsvValue, toCsv } from "@/lib/csv";

describe("lib/csv", () => {
  it("leaves plain values unquoted", () => {
    expect(escapeCsvValue("backlog")).toBe("backlog");
    expect(escapeCsvValue(42)).toBe("42");
    expect(escapeCsvValue(true)).toBe("true");
  });

  it("renders null as an empty field", () => {
    expect(escapeCsvValue(null)).toBe("");
  });

  it("quotes values containing a comma, a quote or a newline", () => {
    expect(escapeCsvValue("Alpha, Beta")).toBe('"Alpha, Beta"');
    expect(escapeCsvValue('say "hi"')).toBe('"say ""hi"""');
    expect(escapeCsvValue("line one\nline two")).toBe('"line one\nline two"');
  });

  it("writes the header from `columns` and orders fields by it", () => {
    const csv = toCsv(
      [
        { title: "Second", status: "todo" },
        { status: "done", title: "First" },
      ],
      ["status", "title"],
    );

    expect(csv.split("\r\n")).toEqual(["status,title", "todo,Second", "done,First"]);
  });

  it("ignores keys not named in `columns` and blanks missing ones", () => {
    const csv = toCsv([{ title: "Only", secret: "hidden" }], ["title", "assignee"]);
    expect(csv).toBe("title,assignee\r\nOnly,");
    expect(csv).not.toContain("hidden");
  });

  it("separates rows with CRLF as RFC 4180 requires", () => {
    expect(toCsv([{ a: "1" }, { a: "2" }], ["a"])).toBe("a\r\n1\r\n2");
  });

  it("emits only the header for an empty row set", () => {
    expect(toCsv([], ["a", "b"])).toBe("a,b");
  });

  it("builds download headers with a sanitised filename", () => {
    const headers = csvResponseHeaders("issues report/2026.csv");
    expect(headers["Content-Type"]).toBe("text/csv; charset=utf-8");
    expect(headers["Content-Disposition"]).toBe(
      'attachment; filename="issues-report-2026.csv"',
    );
    expect(headers["Cache-Control"]).toBe("no-store");
  });
});
/**
 * Streams the issue CSV; requires the `csv_export` flag.
 *
 * Owner D. Query parameters are parsed with `exportIssuesSchema` — the same
 * schema the export UI submits — so `?includeArchived=true` cannot mean one
 * thing in the form and another here.
 *
 * Must call (do not reimplement): can, isEnabled, toCsv
 */

import { PENDING_ISSUE_ID, PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { csvResponseHeaders, toCsv } from "@/lib/csv";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { exportIssuesSchema } from "@/schemas/export";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listIssues } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { Issue } from "@/types/issue";

export const dynamic = "force-dynamic";

const EXPORT_PAGE_LIMIT = 100;

const COLUMNS: readonly string[] = [
  "number",
  "title",
  "status",
  "priority",
  "assigneeId",
  "authorId",
  "dueAt",
  "createdAt",
  "updatedAt",
];

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    const actor = await getActor(orgSlug);
    const { organization } = await getOrganizationSummary(actor, actor.orgId);

    if (!isEnabled("csv_export", buildFlagContext(actor, organization))) {
      return failure("forbidden", "CSV export is not included in this plan.");
    }

    const allowed = can(actor, "issue:read", {
      kind: "issue",
      orgId: actor.orgId,
      projectId: PENDING_PROJECT_ID,
      issueId: PENDING_ISSUE_ID,
      authorId: actor.userId,
      assigneeId: actor.userId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot export issues in this organization.");
    }

    const parsed = exportIssuesSchema.safeParse({
      orgId: actor.orgId,
      projectId: url.searchParams.get("projectId") ?? undefined,
      includeArchived: url.searchParams.get("includeArchived") ?? false,
      format: url.searchParams.get("format") ?? "csv",
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad export parameters.");
    }

    const page = await listIssues(actor, {
      orgId: parsed.data.orgId,
      projectId: parsed.data.projectId,
      includeArchived: parsed.data.includeArchived,
      limit: EXPORT_PAGE_LIMIT,
    });

    if (parsed.data.format === "json") {
      return Response.json({ items: page.items, total: page.total });
    }

    const csv = toCsv(page.items.map(toRow), COLUMNS);
    return new Response(csv, {
      headers: csvResponseHeaders(`taskflow-issues-${organization.slug}.csv`),
    });
  } catch (error) {
    return errorResponse(error);
  }
}

/** Flattens an `Issue` into the scalar row shape `toCsv` accepts. */
function toRow(issue: Issue): Record<string, string | number | boolean | null> {
  return {
    number: issue.number,
    title: issue.title,
    status: issue.status,
    priority: issue.priority,
    assigneeId: issue.assigneeId,
    authorId: issue.authorId,
    dueAt: issue.dueAt,
    createdAt: issue.createdAt,
    updatedAt: issue.updatedAt,
  };
}
